import Foundation

/// 과학 개념 사전 보충: 중학교 교과서 단원 (2015·2022 개정)
extension DoitCurriculum {
    static let scienceMiddleMore: [CurriculumEntry] = [
        // 중1
        ce(.middle, "지권의 변화", ["광물", "조암 광물", "광물의 특성", "조흔색"], "암석을 이루는 작은 알갱이를 광물이라 하고, 그중 암석을 이루는 주된 광물을 조암 광물이라고 해요. 장석과 석영이 가장 많고 휘석, 각섬석, 흑운모, 감람석 등이 있어요. 광물은 색, 조흔색, 굳기, 자성, 염산과의 반응 등으로 구별해요.\n예: 금과 황철석은 겉보기 색이 비슷하지만 조흔색이 금은 노란색, 황철석은 검은색이에요."),
        ce(.middle, "지권의 변화", ["화성암", "심성암과 화산암"], "마그마가 식어서 굳어진 암석을 화성암이라고 해요. 지하 깊은 곳에서 천천히 식으면 광물 결정이 큰 심성암(예: 화강암)이 되고, 지표 근처에서 빨리 식으면 결정이 작은 화산암(예: 현무암)이 돼요. 화강암은 밝은색, 현무암은 어두운색을 띠어요.\n예: 제주도의 돌하르방은 구멍이 많은 현무암으로 만들어요."),
        ce(.middle, "지권의 변화", ["퇴적암과 변성암", "퇴적암", "변성암", "층리"], "퇴적암은 자갈, 모래, 진흙 같은 퇴적물이 쌓여 다져지고 굳어진 암석으로, 층리가 나타나고 화석이 발견되기도 해요. 변성암은 암석이 높은 열과 압력을 받아 성질이 변한 암석이에요.\n예: 셰일이 변성되면 점판암, 편암, 편마암이 되고, 석회암은 대리암, 사암은 규암이 돼요."),
        ce(.middle, "지권의 변화", ["풍화 작용", "풍화", "토양의 생성"], "암석이 오랜 시간에 걸쳐 잘게 부서지거나 성분이 변하는 현상을 풍화라고 해요. 물이 얼었다 녹기를 반복하거나 식물의 뿌리가 자라면서 암석이 부서지고, 지하수나 빗물이 석회암을 녹이기도 해요. 풍화된 암석 조각에 생물이 썩은 물질이 섞이면 토양이 돼요.\n예: 바위틈의 물이 얼면 부피가 늘어나 틈이 점점 벌어져요."),
        ce(.middle, "지권의 변화", ["지진의 규모와 진도", "규모", "진도"], "지진의 세기는 규모와 진도로 나타내요. 규모는 지진이 발생할 때 방출된 에너지의 양으로 정하며 관측 장소와 관계없이 일정하고, 진도는 어떤 지역에서 사람이 느끼는 정도나 피해 정도로 정해서 장소마다 달라요. 보통 진원에서 멀어질수록 진도는 작아져요.\n예: 같은 지진이라도 진앙 가까운 지역은 진도가 크고 먼 지역은 진도가 작아요."),
        ce(.middle, "지권의 변화", ["대륙 이동설", "베게너", "판게아"], "베게너는 과거에 하나로 붙어 있던 대륙(판게아)이 갈라지고 이동하여 현재와 같은 대륙 분포가 되었다고 주장했어요. 대륙 해안선 모양의 일치, 멀리 떨어진 대륙에서 같은 화석이 발견되는 것, 빙하의 흔적 등을 증거로 들었지만, 대륙을 움직이는 힘을 설명하지 못해 당시에는 받아들여지지 않았어요.\n예: 남아메리카 동쪽 해안선과 아프리카 서쪽 해안선은 퍼즐처럼 잘 맞아요."),
        ce(.middle, "여러 가지 힘", ["힘의 표현", "힘의 3요소", "뉴턴(N)"], "과학에서 힘은 물체의 모양이나 운동 상태를 변하게 하는 원인이에요. 힘은 화살표로 나타내는데 화살표의 길이는 힘의 크기, 화살표의 방향은 힘의 방향, 화살표의 시작점은 작용점을 뜻해요. 힘의 단위는 N(뉴턴)이에요.\n예: 공을 발로 차면 공의 운동 방향과 빠르기가 바뀌고, 고무공을 누르면 모양이 바뀌어요."),
        ce(.middle, "여러 가지 힘", ["탄성력", "용수철의 늘어난 길이"], "모양이 변한 물체가 처음 모양으로 돌아가려고 하는 힘을 탄성력이라고 해요. 탄성력은 물체를 변형시킨 힘과 반대 방향으로 작용하고, 변형이 클수록 커져요. 용수철은 일정한 범위 안에서 매단 물체의 무게에 비례하여 늘어나요.\n예: 활시위, 트램펄린, 용수철저울은 탄성력을 이용해요."),
        ce(.middle, "여러 가지 힘", ["마찰력", "friction"], "두 물체의 접촉면에서 물체의 운동을 방해하는 힘을 마찰력이라고 해요. 마찰력은 물체가 움직이려는 방향과 반대 방향으로 작용하고, 접촉면이 거칠수록, 물체의 무게가 클수록 커져요.\n예: 운동화 바닥의 울퉁불퉁한 무늬는 마찰력을 크게 하고, 기계에 윤활유를 넣는 것은 마찰력을 작게 하기 위해서예요."),
        ce(.middle, "생물의 구성과 다양성", ["생물 다양성의 보전", "멸종 위기종", "외래종"], "생물 다양성을 위협하는 원인에는 서식지 파괴, 불법 포획과 남획, 외래종의 유입, 환경 오염과 기후 변화 등이 있어요. 생물 다양성을 보전하기 위해 보호 구역을 지정하고, 멸종 위기종을 보호하며, 국제 협약을 맺어 함께 노력해요.\n예: 황소개구리, 뉴트리아 같은 외래종은 천적이 없어 수가 늘면 토종 생물을 위협해요."),
        ce(.middle, "기체의 성질", ["기체의 압력", "압력"], "기체 입자가 끊임없이 움직이며 용기 벽에 충돌하여 일정한 넓이에 작용하는 힘을 기체의 압력이라고 해요. 기체의 압력은 모든 방향으로 작용하고, 같은 부피 안에서 입자 수가 많거나 온도가 높아 충돌이 많아질수록 커져요.\n예: 풍선에 공기를 불어 넣으면 기체 입자의 충돌로 풍선이 모든 방향으로 고르게 부풀어요."),
        ce(.middle, "물질의 상태 변화", ["물질의 세 가지 상태와 입자 배열", "입자 배열", "물질의 상태"], "고체는 입자가 규칙적으로 빽빽하게 배열되어 모양과 부피가 일정하고, 액체는 입자 배열이 불규칙하고 비교적 자유롭게 움직여 모양은 변하지만 부피는 일정해요. 기체는 입자 사이의 거리가 매우 멀고 자유롭게 움직여 모양과 부피가 모두 일정하지 않아요.\n예: 대부분의 물질은 고체가 될 때 부피가 줄지만, 물은 얼음이 될 때 부피가 늘어나요."),
        ce(.middle, "물질의 상태 변화", ["확산과 증발", "확산", "증발", "입자의 운동"], "물질을 이루는 입자는 스스로 끊임없이 움직이고 있어요. 입자가 스스로 운동하여 퍼져 나가는 현상을 확산, 액체 표면에서 입자가 기체로 떨어져 나가는 현상을 증발이라고 해요. 온도가 높을수록 입자의 운동이 활발해져 확산과 증발이 빨라져요.\n예: 향수 냄새가 방 안에 퍼지는 것은 확산, 젖은 빨래가 마르는 것은 증발이에요."),
        ce(.middle, "물질의 상태 변화", ["상태 변화와 열에너지", "열에너지의 흡수와 방출"], "물질이 융해, 기화, 승화(고체 → 기체)할 때는 주위에서 열에너지를 흡수하고, 응고, 액화, 승화(기체 → 고체)할 때는 열에너지를 방출해요. 상태가 변하는 동안에는 열을 계속 가해도 온도가 일정하게 유지돼요.\n예: 더운 날 마당에 물을 뿌리면 물이 기화하면서 열을 흡수해 시원해지고, 이글루 안에 물을 뿌리면 물이 얼면서 열을 방출해 따뜻해져요."),

        // 중2
        ce(.middle, "물질의 구성", ["원소 기호", "원소 기호 표기법"], "원소 기호는 원소를 간단히 나타내는 기호로, 원소 이름의 알파벳 첫 글자를 대문자로 쓰고, 첫 글자가 같으면 중간 글자 하나를 소문자로 붙여 써요.\n예: 수소 H, 산소 O, 탄소 C, 칼슘 Ca, 구리 Cu, 나트륨 Na"),
        ce(.middle, "물질의 구성", ["불꽃 반응과 선 스펙트럼", "불꽃 반응", "선 스펙트럼"], "일부 금속 원소는 불꽃에 넣으면 원소마다 고유한 색을 나타내는데, 이것을 불꽃 반응이라고 해요. 불꽃 반응의 색이 비슷할 때는 빛을 분광기로 보아 나타나는 선 스펙트럼의 위치와 개수로 원소를 구별해요.\n예: 나트륨은 노란색, 칼륨은 보라색, 구리는 청록색, 리튬과 스트론튬은 빨간색 불꽃 반응을 보여요."),
        ce(.middle, "전기와 자기", ["저항의 직렬연결과 병렬연결", "저항의 연결"], "저항을 직렬로 연결하면 각 저항에 흐르는 전류의 세기가 같고, 전체 전압은 각 저항에 걸리는 전압의 합이에요. 병렬로 연결하면 각 저항에 걸리는 전압이 같고, 전체 전류는 각 저항에 흐르는 전류의 합이에요. 집 안의 전기 기구는 병렬로 연결되어 있어 하나를 꺼도 다른 기구는 계속 쓸 수 있어요.\n예: 2Ω과 3Ω을 직렬로 연결하면 전체 저항은 5Ω이에요."),
        ce(.middle, "전기와 자기", ["전동기", "자기장 속에서 전류가 받는 힘", "모터"], "자기장 속에 있는 도선에 전류가 흐르면 도선이 힘을 받아요. 힘의 방향은 전류의 방향과 자기장의 방향에 모두 수직이고, 전류나 자기장의 방향을 반대로 하면 힘의 방향도 반대가 돼요. 전동기는 이 힘으로 코일을 회전시켜 전기 에너지를 운동 에너지로 바꾸는 장치예요.\n예: 선풍기, 세탁기, 전기 자동차에 전동기가 쓰여요."),
        ce(.middle, "태양계", ["지구의 크기 측정", "에라토스테네스"], "에라토스테네스는 지구는 완전한 구형이고 지구에 들어오는 햇빛은 평행하다는 가정으로 지구의 크기를 처음 측정했어요. 같은 경도에 있는 시에네와 알렉산드리아에서 햇빛이 비치는 각도 차이(7.2°)와 두 도시 사이의 거리(약 925km)를 이용해 원의 중심각과 호의 길이의 비례 관계로 계산했어요.\n예: 7.2° : 360° = 925km : 지구의 둘레이므로 지구의 둘레는 약 46250km예요."),
        ce(.middle, "태양계", ["달의 공전과 위상", "삭과 망", "상현달과 하현달"], "달은 스스로 빛을 내지 못하고 햇빛을 반사하여 빛나며, 약 한 달을 주기로 지구 주위를 공전하면서 모양이 바뀌어 보여요. 달이 태양과 같은 방향에 있으면 보이지 않는 삭, 반대 방향에 있으면 둥근 보름달인 망이 되고, 그 사이에 상현달과 하현달이 보여요.\n예: 음력 15일 무렵에는 보름달(망)을 볼 수 있어요."),
        ce(.middle, "태양계", ["일식과 월식", "일식", "월식"], "일식은 달이 태양을 가리는 현상으로 태양-달-지구가 일직선에 놓이는 삭일 때 일어나요. 월식은 달이 지구의 그림자 속으로 들어가는 현상으로 태양-지구-달이 일직선에 놓이는 망일 때 일어나요. 개기 월식 때 달은 완전히 사라지지 않고 붉게 보여요.\n예: 개기 일식 때는 태양의 대기인 코로나를 관측할 수 있어요."),
        ce(.middle, "태양계", ["태양 활동이 지구에 미치는 영향", "태양풍", "오로라", "자기 폭풍"], "태양 활동이 활발해지면 흑점 수가 많아지고 홍염과 플레어가 자주 나타나며, 태양풍이 강해져요. 이때 지구에서는 오로라가 더 자주 나타나고, 자기 폭풍이나 무선 통신 장애, 인공위성 고장 등이 생길 수 있어요.\n예: 흑점 수는 약 11년을 주기로 많아졌다 적어졌다 해요."),
        ce(.middle, "식물과 에너지", ["광합성", "photosynthesis", "엽록체"], "광합성은 식물이 빛에너지를 이용해 이산화 탄소와 물로 포도당 같은 양분을 만들고 산소를 내놓는 과정이에요. 주로 잎의 엽록체에서 일어나고, 만들어진 포도당은 곧 녹말로 바뀌어 잎에 잠시 저장돼요.\n예: 이산화 탄소 + 물 → (빛에너지, 엽록체) → 포도당 + 산소"),
        ce(.middle, "식물과 에너지", ["광합성에 영향을 미치는 요인", "빛의 세기와 광합성", "이산화 탄소의 농도와 광합성"], "광합성량은 빛의 세기가 셀수록, 이산화 탄소의 농도가 높을수록 증가하다가 어느 정도 이상이 되면 더 이상 증가하지 않아요. 온도는 일정 범위까지는 높을수록 광합성량이 늘지만, 너무 높아지면 오히려 급격히 줄어들어요.\n예: 비닐하우스에서 이산화 탄소를 공급하거나 조명을 켜면 작물의 광합성량을 늘릴 수 있어요."),
        ce(.middle, "식물과 에너지", ["증산 작용", "기공", "공변세포"], "잎의 기공을 통해 물이 수증기 상태로 빠져나가는 현상을 증산 작용이라고 해요. 증산 작용은 뿌리에서 흡수한 물이 잎까지 올라가는 원동력이 되고, 식물의 체온을 조절해요. 기공은 공변세포로 둘러싸여 있고, 주로 낮에 열리고 밤에 닫혀요.\n예: 햇빛이 강하고 바람이 잘 불며 습도가 낮을 때 증산 작용이 활발해요."),
        ce(.middle, "식물과 에너지", ["식물의 호흡", "광합성과 호흡의 비교"], "식물도 살아가는 데 필요한 에너지를 얻기 위해 산소를 흡수하고 포도당을 분해해 이산화 탄소와 물을 내놓는 호흡을 해요. 광합성은 빛이 있을 때만 일어나지만 호흡은 낮과 밤에 관계없이 항상 일어나요. 낮에는 광합성량이 호흡량보다 많아 산소를 내보내요.\n예: 밤에는 광합성이 일어나지 않아 식물이 산소를 흡수하고 이산화 탄소를 내보내요."),
        ce(.middle, "식물과 에너지", ["광합성 산물의 이동과 저장", "체관", "양분의 저장"], "광합성으로 만들어진 녹말은 주로 밤에 물에 잘 녹는 설탕으로 바뀌어 체관을 통해 식물의 각 기관으로 이동해요. 이동한 양분은 호흡이나 생장에 쓰이고, 남은 것은 녹말, 포도당, 단백질, 지방 등으로 바뀌어 저장돼요.\n예: 감자의 덩이줄기와 고구마의 뿌리에는 녹말이, 콩에는 단백질이 많이 저장돼요."),
        ce(.middle, "물질의 특성", ["순물질과 혼합물", "순물질", "혼합물", "균일 혼합물"], "한 종류의 물질로만 이루어진 물질을 순물질, 두 종류 이상의 순물질이 섞여 있는 물질을 혼합물이라고 해요. 소금물처럼 성분이 고르게 섞인 것을 균일 혼합물, 흙탕물처럼 고르지 않게 섞인 것을 불균일 혼합물이라고 해요. 순물질은 녹는점·끓는점이 일정하지만 혼합물은 일정하지 않아요.\n예: 물, 산소, 금은 순물질이고 공기, 우유, 암석은 혼합물이에요."),
        ce(.middle, "물질의 특성", ["밀도", "density"], "밀도는 물질의 질량을 부피로 나눈 값(밀도 = 질량 ÷ 부피)으로, 단위는 g/cm³, g/mL 등을 써요. 밀도는 물질마다 고유한 값을 가지는 물질의 특성이고, 밀도가 작은 물질은 밀도가 큰 물질 위에 떠요. 기체의 밀도는 온도와 압력에 따라 크게 변해요.\n예: 질량 54g, 부피 20cm³인 물질의 밀도는 2.7g/cm³으로, 알루미늄의 밀도와 같아요."),
        ce(.middle, "물질의 특성", ["용해도", "solubility", "포화 용액"], "용해도는 어떤 온도에서 용매 100g에 최대로 녹을 수 있는 용질의 g 수예요. 용질이 최대로 녹아 있는 용액을 포화 용액이라고 해요. 고체의 용해도는 대체로 온도가 높을수록 커지고, 기체의 용해도는 온도가 낮고 압력이 높을수록 커져요.\n예: 탄산음료의 뚜껑을 열면 압력이 낮아져 녹아 있던 이산화 탄소가 빠져나오며 거품이 생겨요."),
        ce(.middle, "물질의 특성", ["녹는점과 끓는점", "끓는점", "녹는점", "어는점"], "고체가 녹기 시작하는 온도를 녹는점, 액체가 끓기 시작하는 온도를 끓는점이라고 해요. 순물질의 녹는점과 어는점은 같고, 물질의 양에 관계없이 일정해서 물질을 구별하는 특성이 돼요. 끓는점은 외부 압력이 높을수록 높아져요.\n예: 1기압에서 물의 끓는점은 100°C이고, 높은 산 위에서는 기압이 낮아 100°C보다 낮은 온도에서 끓어요."),
        ce(.middle, "물질의 특성", ["혼합물의 분리 방법", "증류", "크로마토그래피", "재결정"], "혼합물은 성분 물질의 특성 차이를 이용해 분리해요. 끓는점 차이를 이용하는 증류, 밀도 차이를 이용하는 분별 깔때기, 용해도 차이를 이용하는 재결정, 용매를 따라 이동하는 속도 차이를 이용하는 크로마토그래피가 있어요.\n예: 원유를 끓는점에 따라 분리해 LPG, 휘발유, 등유 등을 얻고, 사인펜 잉크의 색소는 크로마토그래피로 분리해요."),
        ce(.middle, "수권과 해수의 순환", ["수권의 분포", "해수와 담수"], "지구의 물을 수권이라고 하며 약 97%가 해수이고, 나머지 약 3%가 담수예요. 담수는 빙하가 가장 많고 그다음이 지하수이며, 호수와 하천수는 매우 적어요. 우리가 쉽게 쓸 수 있는 물은 주로 하천수, 호수, 지하수예요.\n예: 지구의 물을 100컵이라고 하면 그중 약 97컵이 바닷물이에요."),
        ce(.middle, "수권과 해수의 순환", ["염분", "염류", "염분비 일정 법칙"], "해수에 녹아 있는 여러 가지 물질을 염류라 하고, 해수 1kg에 녹아 있는 염류의 총량을 g 수로 나타낸 것을 염분이라고 해요. 전 세계 해수의 평균 염분은 약 35psu이고, 염류 중에는 염화 나트륨이 가장 많아요. 염분은 지역에 따라 달라도 염류 사이의 비율은 일정한데, 이것을 염분비 일정 법칙이라고 해요.\n예: 강물이 흘러드는 곳이나 비가 많이 오는 곳은 염분이 낮고, 증발이 활발한 곳은 염분이 높아요."),
        ce(.middle, "수권과 해수의 순환", ["해류", "난류와 한류", "우리나라 주변의 해류"], "일정한 방향으로 흐르는 바닷물의 흐름을 해류라고 해요. 저위도에서 고위도로 흐르는 따뜻한 해류를 난류, 고위도에서 저위도로 흐르는 차가운 해류를 한류라고 해요. 우리나라 주변에는 쿠로시오 해류에서 갈라진 황해 난류와 동한 난류, 북쪽에서 내려오는 북한 한류가 흘러요.\n예: 동해에서는 동한 난류와 북한 한류가 만나 조경 수역이 생겨 좋은 어장이 돼요."),
        ce(.middle, "수권과 해수의 순환", ["조석", "밀물과 썰물", "조차"], "해수면이 주기적으로 높아졌다 낮아졌다 하는 현상을 조석이라고 해요. 바닷물이 들어와 해수면이 가장 높아진 때를 만조, 가장 낮아진 때를 간조라 하고, 그 높이 차이를 조차라고 해요. 우리나라에서는 보통 하루에 만조와 간조가 약 두 번씩 나타나요.\n예: 서해안은 조차가 커서 간조 때 넓은 갯벌이 드러나요."),
        ce(.middle, "열과 우리 생활", ["열평형", "thermal equilibrium"], "온도가 다른 두 물체가 접촉하면 열이 온도가 높은 물체에서 낮은 물체로 이동하여, 결국 두 물체의 온도가 같아지는 상태가 되는데 이것을 열평형이라고 해요. 외부와 열을 주고받지 않으면 고온의 물체가 잃은 열량과 저온의 물체가 얻은 열량은 같아요.\n예: 뜨거운 국에 넣어 둔 숟가락이 점점 뜨거워지다가 국과 같은 온도가 돼요."),
        ce(.middle, "열과 우리 생활", ["열팽창", "thermal expansion", "바이메탈"], "물체에 열을 가하면 입자의 운동이 활발해져 입자 사이의 거리가 멀어지므로 부피가 늘어나는데, 이것을 열팽창이라고 해요. 같은 조건에서 열팽창 정도는 물질의 종류에 따라 달라요.\n예: 여름철에 늘어날 것을 대비해 기찻길 레일 사이에 틈을 두고, 바이메탈은 열팽창 정도가 다른 두 금속을 붙여 만든 것이에요."),
        ce(.middle, "열과 우리 생활", ["단열", "단열재"], "열의 이동을 막는 것을 단열이라고 해요. 공기처럼 열을 잘 전달하지 않는 물질을 이용하거나 전도·대류·복사를 막으면 단열 효과가 커져요.\n예: 이중창, 보온병, 아이스박스의 스타이로폼은 단열을 이용해요."),

        // 중3
        ce(.middle, "화학 반응의 규칙과 에너지 변화", ["화학 반응식", "화학 반응식 쓰기", "계수 맞추기"], "화학 반응식은 화학 반응을 화학식과 기호로 나타낸 식으로, 반응물은 왼쪽, 생성물은 오른쪽에 쓰고 화살표로 연결해요. 반응 전후 원자의 종류와 개수가 같도록 화학식 앞에 계수를 맞춰요. 계수의 비는 분자 수의 비와 같아요.\n예: 2H₂ + O₂ → 2H₂O (수소 분자 2개와 산소 분자 1개가 반응해 물 분자 2개가 생성)"),
        ce(.middle, "화학 반응의 규칙과 에너지 변화", ["기체 반응 법칙", "Gay-Lussac's law"], "일정한 온도와 압력에서 기체끼리 반응하여 새로운 기체가 생성될 때, 반응하는 기체와 생성되는 기체의 부피 사이에는 간단한 정수비가 성립해요. 이것을 기체 반응 법칙이라고 해요.\n예: 수소 기체 2부피와 산소 기체 1부피가 반응하면 수증기 2부피가 생성돼요(부피비 2 : 1 : 2)."),
        ce(.middle, "기권과 날씨", ["구름의 생성", "단열 팽창"], "공기 덩어리가 상승하면 주위의 기압이 낮아져 부피가 팽창하고(단열 팽창) 온도가 내려가요. 온도가 이슬점에 이르면 수증기가 응결하여 물방울이나 얼음 알갱이가 생기고, 이것이 모여 구름이 돼요.\n예: 공기가 산을 타고 올라가거나 따뜻한 공기가 찬 공기 위로 올라갈 때 구름이 생겨요."),
        ce(.middle, "기권과 날씨", ["기압", "대기압", "atmospheric pressure"], "공기가 단위 넓이에 작용하는 힘을 기압이라고 해요. 기압은 모든 방향으로 작용하고, 높이 올라갈수록 공기의 양이 줄어 낮아져요. 1기압은 수은 기둥 76cm의 압력과 같고, 약 1013hPa이에요.\n예: 높은 산에 올라가면 과자 봉지가 부풀어 올라요."),
        ce(.middle, "기권과 날씨", ["바람", "해륙풍", "계절풍"], "바람은 두 지점 사이의 기압 차이 때문에 기압이 높은 곳에서 낮은 곳으로 공기가 이동하는 거예요. 낮에는 육지가 빨리 데워져 바다에서 육지로 해풍이, 밤에는 육지에서 바다로 육풍이 불어요. 우리나라는 여름에 남동 계절풍, 겨울에 북서 계절풍이 불어요.\n예: 기압 차이가 클수록 바람이 강하게 불어요."),
        ce(.middle, "기권과 날씨", ["저기압과 고기압의 날씨", "상승 기류와 하강 기류"], "주위보다 기압이 높은 곳이 고기압, 낮은 곳이 저기압이에요. 북반구의 고기압에서는 바람이 시계 방향으로 불어 나가고 하강 기류가 생겨 날씨가 맑아요. 저기압에서는 바람이 시계 반대 방향으로 불어 들어오고 상승 기류가 생겨 구름이 많고 비가 오기 쉬워요.\n예: 일기도에서 등압선이 닫힌 모양이고 가운데 기압이 주위보다 높으면 고기압이에요."),
        ce(.middle, "기권과 날씨", ["강수 과정", "빙정설", "병합설"], "구름 속 물방울이나 얼음 알갱이가 커져서 떨어지는 것이 비나 눈이에요. 중위도·고위도 지방에서는 구름 속 얼음 알갱이(빙정)가 수증기를 받아 커져서 떨어지는 빙정설로, 열대 지방에서는 크고 작은 물방울이 부딪쳐 합쳐지며 커지는 병합설로 설명해요.\n예: 우리나라의 겨울 눈은 빙정이 녹지 않고 그대로 떨어진 거예요."),
        ce(.middle, "운동과 에너지", ["등속 운동", "등속 직선 운동"], "시간이 지나도 속력과 방향이 일정한 운동을 등속 직선 운동이라고 해요. 등속 운동에서 이동 거리는 시간에 비례하므로 시간-이동 거리 그래프는 원점을 지나는 직선이고, 시간-속력 그래프는 시간 축에 나란한 직선이에요. 시간-속력 그래프 아래 넓이는 이동 거리와 같아요.\n예: 무빙워크 위에 가만히 서 있는 사람은 등속 운동을 해요."),
        ce(.middle, "운동과 에너지", ["일의 양", "과학에서의 일", "줄(J)"], "과학에서 일의 양은 물체에 작용한 힘과 힘의 방향으로 이동한 거리의 곱이에요. 단위는 J(줄)이고, 1J은 1N의 힘으로 물체를 힘의 방향으로 1m 이동시킬 때 한 일이에요. 힘의 방향과 이동 방향이 수직이면 한 일은 0이에요.\n예: 무게 20N인 가방을 1.5m 들어 올리면 30J의 일을 해요. 가방을 든 채 수평으로 걸어가면 중력에 대해 한 일은 0이에요."),
        ce(.middle, "운동과 에너지", ["위치 에너지", "중력에 의한 위치 에너지"], "높은 곳에 있는 물체가 가지는 에너지를 중력에 의한 위치 에너지라고 해요. 위치 에너지 = 9.8 × 질량(kg) × 높이(m)이고 단위는 J이에요. 물체를 들어 올린 일만큼 위치 에너지가 증가하고, 물체가 떨어지면 위치 에너지는 운동 에너지로 바뀌어요.\n예: 질량 2kg인 물체를 5m 높이로 들어 올리면 위치 에너지는 9.8 × 2 × 5 = 98J 증가해요."),
        ce(.middle, "운동과 에너지", ["운동 에너지", "kinetic energy"], "운동하는 물체가 가지는 에너지를 운동 에너지라고 하며, 운동 에너지 = 1/2 × 질량 × 속력²이에요. 질량이 2배가 되면 운동 에너지는 2배, 속력이 2배가 되면 운동 에너지는 4배가 돼요.\n예: 질량 2kg인 물체가 3m/s로 움직이면 운동 에너지는 1/2 × 2 × 3² = 9J이에요."),
        ce(.middle, "자극과 반응", ["귀의 구조", "청각", "반고리관", "전정 기관"], "소리는 귓바퀴 → 외이도 → 고막 → 귓속뼈 → 달팽이관 → 청각 신경 → 대뇌로 전달돼요. 귀에는 몸의 회전을 느끼는 반고리관과 몸의 기울어짐을 느끼는 전정 기관도 있어요. 귀인두관은 고막 안팎의 압력을 같게 해 줘요.\n예: 높은 산에 올라 귀가 먹먹할 때 침을 삼키면 귀인두관이 열려 압력이 맞춰져요."),
        ce(.middle, "자극과 반응", ["뉴런", "신경 세포", "감각 뉴런", "연합 뉴런", "운동 뉴런"], "뉴런은 신경계를 구성하는 신경 세포로, 신경 세포체, 가지 돌기, 축삭 돌기로 이루어져요. 자극은 감각 뉴런 → 연합 뉴런 → 운동 뉴런 순서로 전달돼요. 연합 뉴런은 뇌와 척수를 이루며 정보를 판단하고 명령을 내려요.\n예: 뜨거운 냄비를 만지면 손의 감각 뉴런이 자극을 받아들이고, 운동 뉴런이 근육에 명령을 전달해요."),
        ce(.middle, "자극과 반응", ["피부 감각", "감각점", "통점"], "피부에는 통점, 압점, 촉점, 냉점, 온점 같은 감각점이 퍼져 있어 아픔, 누르는 느낌, 접촉, 차가움, 따뜻함을 느껴요. 감각점의 분포는 몸의 부위마다 다르고, 일반적으로 통점이 가장 많아요.\n예: 손끝은 감각점이 많아서 작은 차이도 잘 느껴요."),
        ce(.middle, "생식과 유전", ["사람의 발생", "수정", "난할", "착상"], "정자와 난자가 수정하여 만들어진 수정란은 체세포 분열을 빠르게 반복하는 난할을 하며 수란관을 따라 자궁으로 이동해요. 수정 후 약 일주일이 지나 배아가 자궁 안쪽 벽에 파묻히는 것을 착상이라 하고, 이때부터 임신이 되었다고 해요. 태아는 태반을 통해 어머니와 물질을 교환하며 자라고, 수정 후 약 266일(38주)이 지나면 출산해요.\n예: 난할이 진행될수록 세포 수는 늘어나지만 세포 하나의 크기는 점점 작아져요."),
        ce(.middle, "에너지 전환과 보존", ["에너지 전환", "energy conversion"], "에너지는 한 형태에서 다른 형태로 바뀔 수 있는데, 이것을 에너지 전환이라고 해요. 전기 에너지는 전등에서 빛에너지로, 선풍기에서 운동 에너지로, 전기난로에서 열에너지로 바뀌어요.\n예: 광합성에서는 빛에너지가 화학 에너지로, 자동차 엔진에서는 화학 에너지가 운동 에너지로 전환돼요."),
        ce(.middle, "에너지 전환과 보존", ["에너지 보존 법칙", "law of conservation of energy"], "에너지는 전환되는 과정에서 새로 생기거나 사라지지 않고, 전체 에너지의 양은 항상 일정하게 보존돼요. 이것을 에너지 보존 법칙이라고 해요. 다만 전환 과정에서 일부가 열에너지 등 다시 쓰기 어려운 형태로 바뀌므로 우리가 이용할 수 있는 에너지는 줄어들어요.\n예: 공이 튈 때마다 높이가 낮아지는 것은 역학적 에너지의 일부가 열과 소리 에너지로 바뀌기 때문이고, 전체 에너지는 보존돼요."),
        ce(.middle, "에너지 전환과 보존", ["역학적 에너지 전환", "낙하하는 물체의 에너지 전환"], "물체가 떨어질 때는 위치 에너지가 운동 에너지로, 물체를 위로 던져 올라갈 때는 운동 에너지가 위치 에너지로 바뀌어요. 공기 저항과 마찰을 무시하면 감소한 위치 에너지만큼 운동 에너지가 증가하므로 역학적 에너지는 일정하게 보존돼요.\n예: 롤러코스터는 가장 높은 곳에서 위치 에너지가 가장 크고, 가장 낮은 곳에서 운동 에너지가 가장 커요."),
        ce(.middle, "에너지 전환과 보존", ["전기 에너지", "소비 전력"], "전기 에너지는 전류가 흐를 때 공급되는 에너지로, 다른 형태의 에너지로 쉽게 바꿀 수 있고 먼 곳까지 쉽게 보낼 수 있어요. 전기 기구에 적힌 소비 전력(W)은 1초 동안 사용하는 전기 에너지의 양이에요.\n예: 소비 전력이 100W인 전구를 2시간 켜면 200Wh의 전기 에너지를 써요."),
        ce(.middle, "별과 우주", ["별의 색과 표면 온도", "별의 색깔"], "별의 색은 표면 온도에 따라 달라서, 표면 온도가 높을수록 파란색, 낮을수록 붉은색을 띠어요. 표면 온도가 높은 순서대로 파란색 → 청백색 → 흰색 → 황백색 → 노란색 → 주황색 → 붉은색이에요.\n예: 붉은색인 베텔게우스보다 청백색인 리겔의 표면 온도가 더 높아요."),
        ce(.middle, "별과 우주", ["성단과 성운", "산개 성단", "구상 성단", "성운"], "많은 별이 모여 있는 집단을 성단이라 하고, 별이 엉성하게 모인 산개 성단과 수만~수십만 개의 별이 공 모양으로 빽빽하게 모인 구상 성단이 있어요. 산개 성단은 주로 젊고 파란 별, 구상 성단은 주로 나이 많은 붉은 별로 이루어져요. 성간 물질이 모여 구름처럼 보이는 것은 성운이에요.\n예: 플레이아데스 성단은 산개 성단이에요."),
        ce(.middle, "별과 우주", ["외부 은하", "은하의 분류"], "우리은하 밖에 있는 은하를 외부 은하라고 해요. 허블은 은하를 모양에 따라 타원 은하, 나선 은하(정상 나선, 막대 나선), 불규칙 은하로 분류했어요.\n예: 안드로메다은하는 우리은하와 가까운 나선 은하예요."),
        ce(.middle, "별과 우주", ["우주 팽창", "대폭발 우주론"], "멀리 있는 은하일수록 더 빠르게 멀어지고 있다는 관측 결과는 우주가 팽창하고 있음을 보여 줘요. 우주가 팽창한다는 것은 과거에 우주가 매우 작은 한 점에 모여 있다가 대폭발로 시작되었다는 대폭발 우주론의 근거가 돼요.\n예: 점을 찍은 풍선을 불면 모든 점 사이의 거리가 멀어지는 것처럼 은하 사이의 거리가 멀어져요.")
    ]
}
